<?php session_start();require __DIR__.'/../includes/blog_data.php';$slug=$_GET['article']??'';if(!isset($sparkArticles[$slug])){http_response_code(404);$slug=array_key_first($sparkArticles);}$article=$sparkArticles[$slug];function be($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}$related=array_slice(array_filter($sparkArticles,fn($a)=>$a['title']!==$article['title']),0,3,true);?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo be($article['title']); ?> | SPARK</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-100 text-gray-900"><?php include __DIR__.'/../includes/site_header.php'; ?><main><article class="mx-auto max-w-4xl px-4 py-10 md:py-16"><a href="blog.php" class="font-semibold text-orange-600">← Back to Blog</a><header class="mt-8 text-center"><p class="text-sm font-bold uppercase tracking-widest text-orange-600"><?php echo be($article['category']); ?></p><h1 class="mx-auto mt-3 max-w-3xl text-4xl font-black leading-tight md:text-6xl"><?php echo be($article['title']); ?></h1><p class="mt-5 text-gray-500">Published <?php echo be($article['date']); ?> · SPARK Editorial</p></header><div class="my-10 rounded-2xl bg-white p-5 shadow-sm md:p-10"><img src="../assets/images/<?php echo be($article['image']); ?>" class="mx-auto h-[300px] w-full object-contain md:h-[480px]" alt="<?php echo be($article['title']); ?>"></div><div class="mx-auto max-w-2xl space-y-6 text-lg leading-8 text-gray-700"><?php foreach($article['content'] as $paragraph): ?><p><?php echo be($paragraph); ?></p><?php endforeach; ?></div></article><section class="mx-auto max-w-7xl px-4 pb-12"><h2 class="mb-5 text-2xl font-bold">Related articles</h2><div class="grid gap-5 sm:grid-cols-3"><?php foreach($related as $key=>$item): ?><a href="blog_detail.php?article=<?php echo be($key); ?>" class="rounded-xl bg-white p-4 shadow-sm"><img src="../assets/images/<?php echo be($item['image']); ?>" class="h-40 w-full object-contain"><p class="mt-3 text-xs font-bold uppercase text-orange-600"><?php echo be($item['category']); ?></p><h3 class="mt-1 font-bold"><?php echo be($item['title']); ?></h3></a><?php endforeach; ?></div></section></main><?php include __DIR__.'/../includes/footer.php'; ?></body></html>
